import { motion } from "framer-motion";

export function HeroSection() {
  const scrollToWaitlist = () => {
    const waitlistSection = document.getElementById('waitlist');
    if (waitlistSection) {
      const headerHeight = document.getElementById('header')?.offsetHeight || 0;
      const elementPosition = waitlistSection.getBoundingClientRect().top + window.pageYOffset;
      window.scrollTo({
        top: elementPosition - headerHeight,
        behavior: 'smooth'
      });
    }
  };

  const scrollToHowItWorks = () => {
    const howItWorksSection = document.getElementById('how-it-works');
    if (howItWorksSection) {
      const headerHeight = document.getElementById('header')?.offsetHeight || 0;
      const elementPosition = howItWorksSection.getBoundingClientRect().top + window.pageYOffset;
      window.scrollTo({
        top: elementPosition - headerHeight,
        behavior: 'smooth'
      });
    }
  };

  return (
    <section className="pt-32 pb-20 bg-gradient-to-b from-white to-light">
      <div className="container mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex flex-col lg:flex-row items-center justify-between gap-12">
          <motion.div 
            className="lg:w-1/2 space-y-6"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
          >
            <h1 className="text-4xl md:text-5xl font-bold leading-tight">
              Your Minimalist Health Journey Starts Here
            </h1>
            <p className="text-lg text-gray-600">
              EvolveFit combines clean design with powerful health tracking to help you reach your fitness goals with less noise and more focus.
            </p>
            <div className="flex flex-col sm:flex-row gap-4 pt-4">
              <button 
                onClick={scrollToWaitlist}
                className="px-8 py-3 bg-primary text-white text-center rounded-lg font-medium hover:bg-primary/90 transition-all transform hover:-translate-y-1 shadow-lg shadow-primary/20"
              >
                Join the Waitlist
              </button>
              <button 
                onClick={scrollToHowItWorks}
                className="px-8 py-3 bg-white text-dark text-center border border-gray-300 rounded-lg font-medium hover:border-primary hover:text-primary transition-all transform hover:-translate-y-1"
              >
                Learn More
              </button>
            </div>
            <p className="text-sm text-gray-500">
              🚀 Coming soon — Be among the first to experience EvolveFit
            </p>
          </motion.div>
          <motion.div 
            className="lg:w-1/2"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.5, delay: 0.2 }}
          >
            <div className="relative">
              <div className="absolute inset-0 bg-primary/10 rounded-2xl transform rotate-3"></div>
              <img 
                src="https://images.unsplash.com/photo-1581009146145-b5ef050c2e1e?ixlib=rb-1.2.1&auto=format&fit=crop&w=800&q=80" 
                alt="EvolveFit Dashboard Preview" 
                className="relative z-10 rounded-2xl shadow-xl" 
                width="800" 
                height="600"
              />
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  );
}

"use client";

import React from "react";
import { useRouter } from "next/navigation";
import { FloatingNav } from "./components/Navbar"; // Ensure the path to Navbar is correct
import "./globals.css";

export default function Home() {
  const router = useRouter();

  // Define navigation items for FloatingNav
  const navItems = [
    { name: "Home", link: "/manager" }, // Navigates to the Manager page
    { name: "About Us", link: "#about" }, // Scrolls to the About Us section
    { name: "Login", link: "#" }, // Placeholder for Login route
  ];

  const handleGetStarted = () => {
    router.push("/manager");
  };

  return (
    <div className="min-h-screen bg-background text-black font-sans flex flex-col">
      {/* Floating Navigation Bar */}
      <FloatingNav navItems={navItems} className="top-0" />

      {/* Main Content */}
      <main className="flex-grow flex flex-col items-center justify-center text-center p-8 space-y-8">
        {/* Welcome Message */}
        <section className="max-w-3xl">
          <h1 className="text-5xl md:text-6xl font-bold mb-4">
            Welcome to Food <span className="text-primary">Thought</span>
          </h1>
          <p className="text-lg text-neutral-800 mt-2">
            JOB TO BE DONE: Develop a streamlined management system that
            enhances communication, aligns staff roles, and optimizes operations
            to boost employee satisfaction.
          </p>
        </section>

        {/* Get Started Button */}
        <section>
          <button
            onClick={handleGetStarted}
            className="mt-6 px-8 py-3 bg-secondary text-white text-lg font-semibold rounded-full shadow-md hover:bg-primary-dark transition-all"
          >
            Get Started
          </button>
        </section>
      </main>

      {/* About Us Section */}
      <section id="about" className="py-20 bg-white text-neutral-900 text-center">
        <div className="max-w-3xl mx-auto">
          <h2 className="text-4xl font-bold mb-4">About Us</h2>
          <p className="text-lg text-gray-700">
            At Food Thought, we are committed to providing solutions that streamline
            management, enhance communication, and improve staff satisfaction in the
            food industry. Our system is designed to meet the unique challenges faced
            by managers and employees alike.
          </p>
        </div>
      </section>
    </div>
  );
}
